body.script:
(function(){
        var frame=document.getElementById("korona-runtime");
        var html=new TextDecoder().decode(Uint8Array.from(atob(""),function(c){return c.charCodeAt(0)}));
        var params=new URLSearchParams(location.search);
        function unpack(value){if(!value||value.length>12000||!/^[A-Za-z0-9_-]+$/.test(value))return null;try{var normalized=value.replace(/-/g,"+").replace(/_/g,"/");return JSON.parse(atob(normalized+"=".repeat((4-normalized.length%4)%4)))}catch(error){return null}}
        var launch={target:unpack(params.get("target")),wisps:unpack(params.get("wisps")),apiOrigin:unpack(params.get("api"))};
        var base=new URL("./",location.href).href;
        var escapedBase=base.replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;");
        var serialized=JSON.stringify(launch).replace(/</g,"\u003c");
        var injected='<base href="'+escapedBase+'"><script>window.__KORONA_RUNTIME_LAUNCH__='+serialized+';<\/script>';
        frame.srcdoc=html.replace(/<head(\s[^>]*)?>/i,function(head){return head+injected});
        window.addEventListener("message",function(event){var data=event.data||{};if(event.source!==frame.contentWindow||data.type!=="korona-runtime")return;if(window.parent!==window)window.parent.postMessage(data,"*")});
      })()
